namespace sv_aafdeb1737ea4965ad018934bb828792.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Blazor Server, Scoped lifetime = one instance per circuit (user session).
/// </summary>
public class ThemeService
{
    private Theme _currentTheme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme CurrentTheme
    {
        get => _currentTheme;
        set
        {
            if (_currentTheme == value) return;
            _currentTheme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever theme or accent color changes.
    /// All subscribing components call StateHasChanged in response.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island that lives in the static layout and reacts to theme changes *@
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="badge" style="background-color: @ThemeService.AccentColor; cursor: pointer;"
      title="Current theme" @onclick="CycleTheme">
    @GetThemeIcon() @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void CycleTheme()
    {
        ThemeService.CurrentTheme = ThemeService.CurrentTheme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@* Reusable toggle — can be placed on any interactive page *@
@inject ThemeService ThemeService
@implements IDisposable

<div class="d-flex align-items-center gap-2">
    <label>Theme:</label>
    <select class="form-select form-select-sm w-auto" @bind="SelectedTheme">
        <option value="@Theme.Light">Light</option>
        <option value="@Theme.Dark">Dark</option>
        <option value="@Theme.System">System</option>
    </select>
</div>

@code {
    private Theme SelectedTheme
    {
        get => ThemeService.CurrentTheme;
        set => ThemeService.CurrentTheme = value;
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card p-4" style="max-width: 400px;">
    <div class="mb-3">
        <label class="form-label">Theme</label>
        <select class="form-select" @bind="SelectedTheme">
            <option value="@Theme.Light">Light</option>
            <option value="@Theme.Dark">Dark</option>
            <option value="@Theme.System">System</option>
        </select>
    </div>

    <div class="mb-3">
        <label class="form-label">Accent Color</label>
        <input type="color" class="form-control form-control-color"
               value="@ThemeService.AccentColor"
               @onchange="OnAccentColorChanged" />
        <small class="text-muted">@ThemeService.AccentColor</small>
    </div>

    <div class="mt-3 p-2 rounded" style="background-color: @ThemeService.AccentColor; color: white;">
        Preview: accent color applied
    </div>
</div>

@code {
    private Theme SelectedTheme
    {
        get => ThemeService.CurrentTheme;
        set => ThemeService.CurrentTheme = value;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

